# Force a FRESH import. Colab keeps modules in memory across cell runs, so a prior
# import would otherwise shadow the freshly-unpacked files — which is what made the
# bf16 fix look like it "did nothing" (the old fp16 module stayed loaded). Purge, re-import.
import hashlib
for _m in ("config_e_naturalistic_frame", "detector_frozen", "stage3_transfer", "extract_adapter"):
    sys.modules.pop(_m, None)
import config_e_naturalistic_frame as E
E.CFG.RUN_MONITOR = MONITOR   # wire the toggle (per-model JSON is written incrementally after each variant)
print("[loaded] driver SHA-256", hashlib.sha256(open(E.__file__, "rb").read()).hexdigest()[:16],
      "(expect d1aac57d — the v3.3.1 build (v3.3 scoring + memory-safe GPU load); if it differs, Restart runtime)")
E.main()
